// Fail-closed auth. This endpoint drives a whole campaign run — sourcing real people and
// drafting real copy — so an open endpoint here is worse than on any single stage.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Validate the run request before anything downstream moves.
//
// Deliberately re-validates rather than trusting VIO-source-leads to do it: this workflow decides
// how many people get sourced and drafted, and a gate that delegates its own precondition is not
// a gate. Type-checked, not coerced — String(['oryoniq']) === 'oryoniq'.
const b = $input.first().json || {};
if (typeof b.product !== 'string') {
  throw new Error(`REFUSED: 'product' must be a string, got ${Array.isArray(b.product) ? 'array' : typeof b.product}`);
}
const product = b.product.trim().toLowerCase();
if (!['oryoniq', 'visioneerit'].includes(product)) {
  throw new Error(`REFUSED: unknown product '${b.product}'. Known: oryoniq, visioneerit`);
}

// This run is FREE by design: Apollo's search costs nothing and the opener needs only a name,
// title and company — all of which the free search returns. Revealing the address, verifying it,
// building a page and enrolling all cost money or reach a person, and none of them happen here.
// They are separate gated tools, each holding its own approval. That is why this endpoint can be
// handed to someone to press without a budget conversation first.
const MAX = 25;
const asked = Number(b.limit);
const limit = Number.isFinite(asked) && asked > 0 ? Math.min(Math.floor(asked), MAX) : 5;

return { json: { product, limit, limit_capped: Number.isFinite(asked) && asked > MAX,
                 started_at: new Date().toISOString() } };

// VIO-source-leads returns ONE item carrying a leads[] array. The drafting stage runs per lead,
// so fan out to one item each. An empty result must end the run cleanly rather than handing an
// empty array to a stage that would then draft nothing and report success.
const src = $input.first().json || {};
const leads = Array.isArray(src.leads) ? src.leads : [];
const run = $('Resolve Run').first().json;

if (leads.length === 0) {
  return [{ json: { _no_leads: true, product: run.product,
                    returned_by_apollo: src.returned_by_apollo ?? 0,
                    reason: 'Apollo returned no emailable leads for this ICP' } }];
}

return leads.map((l) => ({ json: {
  ...l,
  product: src.product,
  source_config: src.source_config,
  _run_started_at: run.started_at,
} }));

// Collect the per-lead drafts and state plainly what did and did not happen. The boundary is
// restated in the response because whoever reads this — including a human about to approve the
// next step — should not have to infer that nothing was spent and nobody was contacted.
const scrub = (v) => Array.isArray(v) ? v.map(scrub)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, scrub(x)]))
  : (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);

const run = $('Resolve Run').first().json;
// Carry the source stage's own counts through. Reporting `drafted` alone hides the case
// that matters: leads sourced but never drafted. 8 in / 1 out looked fine until these
// two numbers sat next to each other.
const src = $('Source Leads (free)').first().json || {};
const items = $input.all().map((i) => i.json || {});

if (items.length === 1 && items[0]._no_leads) {
  return [{ json: scrub({ ok: true, product: run.product, drafted: 0,
                          note: items[0].reason, credits_spent: 0, contacted: 0 }) }];
}

const drafts = items.map((r) => ({
  first_name: r.lead ? String(r.lead).split(' · ')[0] : (r.first_name || ''),
  lead: r.lead || '',
  opener: r.opener || '',
  email: r.email || '',
  email_complete: r.email_complete === true,
  missing: r.missing || [],
}));

return [{ json: scrub({
  ok: true,
  product: run.product,
  requested: run.limit,
  returned_by_apollo: src.returned_by_apollo ?? null,
  emailable: src.emailable ?? null,
  drafted: drafts.length,
  all_emailable_drafted: (src.emailable ?? null) === drafts.length,
  credits_spent: 0,
  contacted: 0,
  ran: ['source_leads_free', 'draft_opener'],
  next_step: 'reveal_contacts — GATED. Costs one Apollo credit per lead and requires a human '
           + 'approval in Slack. Nothing below has happened yet.',
  note: 'Apollo free search + OpenAI drafting only. No address was revealed, no email verified, '
      + 'no page built, nobody enrolled or contacted.',
  drafts,
}) }];
